WITH eu AS (SELECT COALESCE(e.cargo = 'Agente de prospecção', false) AS agente, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT r.id, r.numero, r.situacao, r.regras, r.criado_em, r.fechada_em, count(DISTINCT l.id) AS banners, count(DISTINCT l.id) FILTER (WHERE l.situacao = 'pronto') AS prontos, count(DISTINCT l.id) FILTER (WHERE l.situacao IN ('na_fila', 'gerando')) AS gerando, count(DISTINCT l.id) FILTER (WHERE l.situacao = 'falhou') AS falharam, count(a.id) AS avaliacoes, avg(a.nota) AS media FROM banner_lab_rodadas r JOIN eu ON (eu.admin OR eu.agente) LEFT JOIN banner_lab l ON l.rodada_id = r.id LEFT JOIN banner_lab_avaliacoes a ON a.lab_id = l.id GROUP BY r.id, r.numero, r.situacao, r.regras, r.criado_em, r.fechada_em ORDER BY r.numero DESC LIMIT 20
